183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
186	        if (ownerFieldsDto != null) {
187	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
188	        }
189	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
190	        if (!missingFields.isEmpty()) {
191	            throw new MissingOwnerFieldsException(missingFields);
192	        }
193	        HttpHeaders headers = new HttpHeaders();
194	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
195	        Collection<Owner> sameLastName =
196	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
197	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
198	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
199	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
200	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
201	        disposableEmailDomainValidator.validate(owner.getEmail());
202	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
203	        rejectIfDuplicateIdentity(owner);
204	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
205	        registrationDateValidator.validate(owner.getRegistrationDate());
206	        if (owner.getRegistrationDate() == null) {
207	            owner.setRegistrationDate(LocalDate.now());
208	        }
209	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
210	        LocalDate registrationDate = owner.getRegistrationDate();
211	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
212	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
213	            throw new DailyOwnerLimitException(registrationDate);
214	        }
215	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
216	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
217	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
218	            throw new CityOwnerLimitException(owner.getCity());
219	        }
220	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
221	        owner.setCustomerCode(customerCodeGenerator.generate(
222	            region, owner.getTelephone(), owner.getLastName()));
223	        this.clinicService.saveOwner(owner);
224	        ownerAuditLogger.ownerCreated(owner);
225	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
226	        headers.setLocation(UriComponentsBuilder.newInstance()
227	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
228	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
229	    }
