231	    /**
232	     * Assigns the household attributes of an owner about to be created, without touching any
233	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
234	     * name and postcode, so every owner in the same household shares it automatically regardless of
235	     * creation order. The new owner's household size after this create is recorded: the existing
236	     * members that share its household (same last name and postcode) plus the owner itself.
237	     *
238	     * @return the existing members of the owner's household (empty when it starts a new household)
239	     */
240	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
241	        owner.setHouseholdId(householdIdGenerator.generate(owner));
242	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
243	        owner.setHouseholdSize(members.size() + 1);
244	        return members;
245	    }
246	
247	    /**
248	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
249	     * When the owner joins an existing household (same last name and postcode) it is rejected as a
250	     * household duplicate, unless the request declared {@code sharesHousehold}: a declared member is
251	     * created and, being knowingly registered, is not treated as a suspected duplicate. When the
252	     * owner starts a new household the ordinary possible-duplicate detection runs.
253	     *
254	     * @throws HouseholdDuplicateException if the owner joins an existing household without opting in
255	     */
256	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
257	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
258	        if (householdMembers.isEmpty()) {
259	            flagPossibleDuplicate(owner, sameLastName);
260	            return;
261	        }
262	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
263	            throw new HouseholdDuplicateException(owner.getHouseholdId());
264	        }
265	        owner.setPossibleDuplicate(false);
266	        owner.setPossibleDuplicateOf(null);
267	    }
268	
269	    /**
270	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
271	     * owner. A full-key match requires an equal telephone, so only owners with the same
272	     * (already normalized) telephone are compared.
273	     *
274	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
275	     */
276	    private void rejectIfDuplicateIdentity(Owner owner) {
277	        Collection<Owner> sameTelephone = this.clinicService.findOwnersByTelephone(owner.getTelephone());
278	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
279	            throw new DuplicateIdentityException(IdentityKey.of(owner));
280	        }
281	    }
282	
283	    /**
284	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
285	     * existing owner's last name and postcode with a different telephone. The matching owner's id
286	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
287	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
288	     * seen here is guaranteed not to be a hard duplicate.
289	     */
290	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
291	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
292	        owner.setPossibleDuplicate(match != null);
293	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
294	    }
