325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
328	        Owner owner = this.clinicService.findOwnerById(ownerId);
329	        if (owner == null) {
330	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
331	        }
332	        HttpHeaders headers = new HttpHeaders();
333	        Pet pet = petMapper.toPet(petFieldsDto);
334	        owner.setId(ownerId);
335	        pet.setOwner(owner);
336	        pet.getType().setName(null);
337	        this.clinicService.savePet(pet);
338	        PetDto petDto = petMapper.toPetDto(pet);
339	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
340	            .buildAndExpand(pet.getId()).toUri());
341	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
342	    }
