344	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
345	    @Override
346	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
347	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
348	        if (currentOwner != null) {
349	            Pet currentPet = this.clinicService.findPetById(petId);
350	            if (currentPet != null) {
351	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
352	                currentPet.setName(petFieldsDto.getName());
353	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
354	                this.clinicService.savePet(currentPet);
355	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
356	            }
357	        }
358	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
359	    }
