18	
19	import java.util.Locale;
20	import java.util.Map;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes a submitted address to its canonical stored form: surrounding whitespace is
26	 * trimmed, internal runs of whitespace are collapsed to a single space, the text is
27	 * upper-cased and common abbreviations are expanded to their full words (e.g. {@code ST}
28	 * to {@code STREET}). An absent (null) address is left as {@code null}; an address that is
29	 * blank once trimmed normalizes to an empty string.
30	 */
31	@Component
32	public class AddressNormalizer {
33	
34	    /** Whole-word abbreviations expanded to their canonical full form, keyed upper-cased. */
35	    private static final Map<String, String> ABBREVIATIONS = Map.of(
36	        "ST", "STREET",
37	        "RD", "ROAD",
38	        "AVE", "AVENUE");
39	
40	    /**
41	     * @param address the raw submitted address (may be {@code null})
42	     * @return {@code null} if the input is {@code null}; otherwise the trimmed, whitespace-collapsed,
43	     *         upper-cased address with common abbreviations expanded (empty when blank)
44	     */
45	    public String normalize(String address) {
46	        if (address == null) {
47	            return null;
48	        }
49	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
50	        if (collapsed.isEmpty()) {
51	            return collapsed;
52	        }
53	        String[] tokens = collapsed.split(" ");
54	        StringBuilder result = new StringBuilder(collapsed.length());
55	        for (int i = 0; i < tokens.length; i++) {
56	            if (i > 0) {
57	                result.append(' ');
58	            }
59	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
60	        }
61	        return result.toString();
62	    }
63	}
