17	package org.springframework.samples.petclinic.rest.validation;
18	
19	import java.util.regex.Pattern;
20	
21	import org.springframework.samples.petclinic.util.CountryCallingCodes;
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes a submitted telephone to its canonical stored form in E.164: spaces, dashes
26	 * and brackets are stripped; a leading '+' and country code are kept when present,
27	 * otherwise the default country code '+61' is assumed and a single leading '0' is dropped
28	 * from the national digits. The result must carry 8 to 15 digits after the '+', and for a
29	 * recognised country code the national number (the digits after the country code) must be
30	 * exactly the length that country requires ('+61' => 9, '+1' => 10).
31	 */
32	@Component
33	public class TelephoneNormalizer {
34	
35	    /** Formatting characters removed before interpreting the number. */
36	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
37	
38	    /** Country code assumed when the submitted number carries no leading '+'. */
39	    private static final String DEFAULT_COUNTRY_CODE = "61";
40	
41	    /** The digits following the '+' must number between 8 and 15 inclusive. */
42	    private static final Pattern E164_DIGITS = Pattern.compile("[0-9]{8,15}");
43	
44	    /**
45	     * @param telephone the raw submitted telephone (may be {@code null})
46	     * @return the telephone in E.164 form, i.e. a '+' followed by 8 to 15 digits
47	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
48	     */
49	    public String normalize(String telephone) {
50	        String cleaned = telephone == null ? "" : SEPARATORS.matcher(telephone.trim()).replaceAll("");
51	        String digits = cleaned.startsWith("+") ? cleaned.substring(1) : toDefaultCountry(cleaned);
52	        if (!E164_DIGITS.matcher(digits).matches() || !hasValidNationalLength(digits)) {
53	            throw new InvalidTelephoneException(telephone);
54	        }
55	        return "+" + digits;
56	    }
57	
58	    /**
59	     * Applies the default country code to national digits, dropping a single leading '0'.
60	     */
61	    private String toDefaultCountry(String national) {
62	        String trunkless = national.startsWith("0") ? national.substring(1) : national;
63	        return DEFAULT_COUNTRY_CODE + trunkless;
64	    }
65	
66	    /**
67	     * Checks the national number (the digits after the country code) against the length its
68	     * country code requires. The longest matching country code wins, so a '+61' number is
69	     * never mistaken for a shorter code. Country codes outside
70	     * {@link CountryCallingCodes#NATIONAL_NUMBER_LENGTHS} carry no additional constraint.
71	     */
72	    private boolean hasValidNationalLength(String digits) {
73	        String countryCode = CountryCallingCodes.prefixOf(digits);
74	        if (countryCode == null) {
75	            return true;
76	        }
77	        return digits.length() - countryCode.length()
78	            == CountryCallingCodes.NATIONAL_NUMBER_LENGTHS.get(countryCode);
79	    }
80	}
