18	import org.springframework.samples.petclinic.util.LocalityResolver;
19	import org.springframework.samples.petclinic.util.Sha256Hex;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Builds an owner's customer code, formatted {@code '<REGION>-<HASH8>'} where {@code REGION}
24	 * is the region code derived from the postcode and {@code HASH8} the first 8 upper-case hex
25	 * characters of SHA-256 over the normalized telephone concatenated with the last name,
26	 * e.g. {@code 'NSW-3F2A9C1E'}.
27	 */
28	@Component
29	public class CustomerCodeGenerator {
30	
31	    /** Separator between the region and hash segments of a customer code. */
32	    private static final char SEPARATOR = '-';
33	
34	    /** Number of hex characters taken from the SHA-256 digest for the hash segment. */
35	    private static final int HASH_LENGTH = 8;
36	
37	    /**
38	     * Generate a customer code for a new owner.
39	     *
40	     * @param region    the region code derived from the owner's postcode; forms the prefix
41	     * @param telephone the owner's normalized telephone; hashed with the last name to form the suffix
42	     * @param lastName  the owner's last name; hashed with the telephone to form the suffix
43	     * @return the formatted customer code
44	     */
45	    public String generate(String region, String telephone, String lastName) {
46	        return region + SEPARATOR + Sha256Hex.upperHexPrefix(telephone + lastName, HASH_LENGTH);
47	    }
48	
49	    /**
50	     * Extract the region segment from a customer code, i.e. the part before the first
51	     * {@value #SEPARATOR}. Yields {@link LocalityResolver#UNKNOWN} when the code is absent
52	     * or carries no region segment.
53	     *
54	     * @param customerCode a customer code produced by {@link #generate}, or {@code null}
55	     * @return the region code embedded in {@code customerCode}
56	     */
57	    public static String regionOf(String customerCode) {
58	        if (customerCode == null) {
59	            return LocalityResolver.UNKNOWN;
60	        }
61	        int separator = customerCode.indexOf(SEPARATOR);
62	        return separator < 0 ? LocalityResolver.UNKNOWN : customerCode.substring(0, separator);
63	    }
64	}
