25	 * rolls forward to the following Monday; any weekday is returned unchanged.
26	 */
27	public abstract class BusinessDayResolver {
28	
29	    /**
30	     * Return the given date if it is a weekday, otherwise the next Monday when it
31	     * falls on a Saturday or Sunday.
32	     */
